import hashlib
import json
import sys
from pathlib import Path

sys.path.insert(0, "/repo")
from app.api import handlers

# Isolated project root for tests (bash read-only on repo, so use /tmp).
handlers.PROJECT_ROOT = Path("/tmp/fakeroot")
handlers.DATA_DIR = handlers.PROJECT_ROOT / "data"


def expect(params, expected_status):
    status, body = handlers.handle_file_digest(params)
    assert status == expected_status, (params, status, body)
    return body


# --- 400 cases ---
assert expect({}, 400) == {"error": "invalid path"}
assert expect({"path": None}, 400) == {"error": "invalid path"}
assert expect({"path": 5}, 400) == {"error": "invalid path"}
assert expect({"path": ""}, 400) == {"error": "invalid path"}
assert expect({"path": "/etc/passwd"}, 400) == {"error": "invalid path"}
assert expect({"path": "/root.txt"}, 400) == {"error": "invalid path"}
assert expect({"path": "sub//a b.txt"}, 400) == {"error": "invalid path"}
assert expect({"path": "./root.txt"}, 400) == {"error": "invalid path"}
assert expect({"path": "sub/./a b.txt"}, 400) == {"error": "invalid path"}
assert expect({"path": "../root.txt"}, 400) == {"error": "invalid path"}
assert expect({"path": "sub/../../etc/passwd"}, 400) == {"error": "invalid path"}
assert expect({"path": "sub/"}, 400) == {"error": "invalid path"}
assert expect({"path": "."}, 400) == {"error": "invalid path"}
assert expect({"path": ".."}, 400) == {"error": "invalid path"}

# --- 404 cases ---
assert expect({"path": "missing.txt"}, 404) == {"error": "not found"}
assert expect({"path": "sub/missing.txt"}, 404) == {"error": "not found"}
assert expect({"path": "sub"}, 404) == {"error": "not found"}  # directory, not a file
assert expect({"path": "sub/deep/-leading.txt/x"}, 404) == {"error": "not found"}

# --- 200 cases: digest must equal script output ---
def expected_digest(rel):
    data = Path("/tmp/fakeroot/data", rel).read_bytes()
    return {
        "file": f"data/{rel}",
        "bytes": len(data),
        "sha256": hashlib.sha256(data).hexdigest(),
    }


for rel in ["root.txt", "sub/a b.txt", "sub/deep/-leading.txt", ".hidden", "a;b.txt"]:
    body = expect({"path": rel}, 200)
    assert body == expected_digest(rel), (rel, body)

print("ALL HANDLER TESTS PASSED")
PY
cd /repo && python /tmp/test_handler.py"}

